content.text:
The pass-2 hidden states are on disk (78 texts × 13 hidden indices × 1,754 tokens). Indices 15/19/23 are the inputs of the three late full-attention layers, and `q_proj` has 4,096 rows: query plus gate for 8 heads of 256.

I'll look for a "repetition state" direction with a content-matched contrast. In each loop text, copy k at offset s holds the same tokens as the source period c0 (the period just before the onset) at offset s - P. So the mean difference h(c2..c4) - h(c0) at matched tokens isolates "being a repeat" while holding content fixed. I compute it on the normalized layer input (x/rms · (1+w), what the gate actually reads) at layers 15/19/23. Then I check how the projection on it is distributed over:
- pre-loop reasoning,
- c0..c4,
- the thinking, final-answer prose and final-answer code of passing and extra-block answers.

The final-answer code is legitimate copying of a drafted solution.

To limit overfitting I build the direction on half of the loop texts and evaluate on the other half. A clean separation (copies far above normal thinking and answer code) means gate-based selective suppression is viable. If the answer code projects as high as loop copies, the selective approach fails and I'll move to the interface failures.

```python
# Hypothesis: a content-matched 'repeat' direction (copies minus source period) at layer inputs 15/19/23 separates loop copies from normal thinking AND from final-answer code
def labels_full(i):
    m = meta2[i]; ids_, offs_, _ = SEG[i]; text = texts2[i]; pc_ = m['prompt_chars']
    lab = np.full(len(ids_), -1)
    st_ = np.array([s_ for s_,_ in offs_])
    if m['kind']=='loop':
        rel_ = st_ - pc_ - m['onset_char']; P_ = m['period_char']
        lab = np.where(st_ < pc_, -1, np.where(rel_ < -P_, 10, np.where(rel_ < 0, 0, 1 + np.maximum(rel_,0)//P_)))
    else:
        te = text.find('</think>')
        code_spans = [(mm.start(), mm.end()) for mm in re.finditer(re.escape(FENCE)+r'python\n.*?'+re.escape(FENCE), text[te:], re.S)]
        lab = np.where(st_ < pc_, -1, np.where(st_ < te, 20, 21))
        for a_,b_ in code_spans:
            lab[(st_ >= te+a_) & (st_ < te+b_)] = 22
    return lab
LAB = [labels_full(i) for i in range(78)]
# matched pairs: token in copy k at char s  <->  token in c0 at char s - k*P (same token id)
def matched_pairs(i):
    m = meta2[i]; ids_, offs_, _ = SEG[i]; lab = LAB[i]
    st_ = {s_: t for t,(s_,_) in enumerate(offs_)}
    pr_ = []
    for t,(s_,_) in enumerate(offs_):
        k = lab[t]
        if 1 <= k <= 4:
            t0 = st_.get(s_ - k*m['period_char'])
            if t0 is not None and lab[t0]==0 and ids_[t0]==ids_[t]: pr_.append((t, t0, k))
    return pr_
PAIRS = {i: matched_pairs(i) for i in loop_ix}
print('matched pairs per text (median):', np.median([len(v_) for v_ in PAIRS.values()]), ' texts with 0 pairs:', sum(len(v_)==0 for v_ in PAIRS.values()))
rngp = np.random.RandomState(0); perm_ = rngp.permutation(loop_ix); A_ix, B_ix = sorted(perm_[:24]), sorted(perm_[24:])
DIRS = {}
for L_ in [15,19,23]:
    k_ = idx2.index(L_)
    Hk = np.asarray(H2[:, k_], dtype=np.float32)  # 78 x T x 1024
    lnw = load_original(f'model.language_model.layers.{L_}.input_layernorm.weight').numpy()
    def xhat(i, ts): 
        x_ = Hk[i, ts]; return x_ / np.sqrt((x_**2).mean(-1, keepdims=True) + 1e-6) * (1 + lnw)
    diffs = []
    for i in A_ix:
        pr_ = [(t,t0) for t,t0,k in PAIRS[i] if k>=2]
        if pr_: diffs.append((xhat(i,[a for a,_ in pr_]) - xhat(i,[b for _,b in pr_])).mean(0))
    d_ = np.mean(diffs, 0); d_ /= np.linalg.norm(d_); DIRS[L_] = d_
    out_ = {}
    for i in range(78):
        pj = xhat(i, np.arange(len(LAB[i]))) @ d_
        if meta2[i]['kind']=='loop' and i in A_ix: continue
        for code_ in set(LAB[i]) - {-1}:
            out_.setdefault(code_, []).append(pj[LAB[i]==code_])
    names_ = {10:'pre',0:'c0',1:'c1',2:'c2',3:'c3',4:'c4',20:'think',21:'ans_text',22:'ans_code'}
    print(f'L{L_} input:', ' '.join(f"{names_[c_]} {np.mean(np.concatenate(v_)):.2f}+-{np.std(np.concatenate(v_)):.2f}" for c_,v_ in sorted(out_.items())))
    del Hk
